const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={configured:false,servers:[],games:[],selectedGame:'hytale',serverId:null,status:null,resources:null,settings:null,logs:[],events:null,current:'servers',configFile:'config.json',appUpdate:null,players:null};
async function api(url,opts={}){const headers=opts.body instanceof FormData?{}:{'Content-Type':'application/json'};if(state.serverId)headers['X-HSM-Server']=state.serverId;const res=await fetch(url,{...opts,headers:{...headers,...(opts.headers||{})}});let body=null;try{body=await res.json()}catch{}if(res.status===401&&!url.includes('/login')){showAuth(false);throw new Error('Authentication required')}if(!res.ok)throw new Error(body?.error||`${res.status} ${res.statusText}`);return body}
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.className='toast show'+(error?' error':'');clearTimeout(toast.t);toast.t=setTimeout(()=>el.className='toast',3000)}
function fmtBytes(n){if(!n)return'—';const u=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return`${n.toFixed(i>1?1:0)} ${u[i]}`}
function fmtUptime(sec){if(!sec)return'—';const d=Math.floor(sec/86400),h=Math.floor(sec%86400/3600),m=Math.floor(sec%3600/60);return d?`${d}d ${h}h`:h?`${h}h ${m}m`:`${m}m`}
function fmtDate(v){try{return new Date(v).toLocaleString()}catch{return v}}function fmtTime(v){try{return new Date(v).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})}catch{return''}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function selectedSummary(){return state.servers.find(s=>s.id===state.serverId)}
function statusLabel(s){if(s?.state==='crashed')return `Crashed (exit ${s.exitCode})`;if(s?.state==='starting')return'Starting';if(s?.state==='stopping')return'Stopping';if(s?.installBusy||s?.state==='installing')return'Installing';if(s?.state==='not-installed'||s?.installed===false)return'Not installed';if(s?.running)return'Online';return'Stopped'}
function gameLabel(id){return ({hytale:'Hytale','minecraft-java':'Minecraft Java','terraria':'Terraria','runescape-dragonwilds':'RuneScape: Dragonwilds'})[id]||'Unknown game'}
function gameLogo(id){const files={'hytale':'hytale.svg','minecraft-java':'minecraft-java.svg','terraria':'terraria.svg','runescape-dragonwilds':'runescape-dragonwilds.svg'};const file=files[id]||files.hytale;return '<img src="/assets/games/'+file+'" alt="" loading="eager" decoding="async">'}
function statusDotClass(s){if(s?.state==='crashed')return'crashed';if(s?.state==='starting'||s?.state==='stopping'||s?.installBusy||s?.state==='installing')return'busy';if(s?.running)return'online';return''}
async function boot(){const b=await api('/api/bootstrap');state.configured=b.configured;if(!b.configured){showAuth(true);return}try{await api('/api/servers');showApp()}catch{showAuth(false)}}
function showAuth(setup){$('#app').classList.add('hidden');$('#auth').classList.remove('hidden');$('#auth-title').textContent=setup?'Create admin account':'Sign in';$('#auth-copy').textContent=setup?'Secure this server manager.':'Manage your Hytale servers.';$('#auth-submit').textContent=setup?'Create account':'Sign in';$('#auth-pass').autocomplete=setup?'new-password':'current-password';$('#auth-form').dataset.mode=setup?'setup':'login'}
async function showApp(){$('#auth').classList.add('hidden');$('#app').classList.remove('hidden');await loadServers(true);if(state.serverId)await loadSelected();clearInterval(state.poll);state.poll=setInterval(async()=>{await loadServers(false);if(state.serverId){await refreshStatus();await loadLogs()}await refreshResources()},2000);clearInterval(state.playerPoll);state.playerPoll=setInterval(()=>{if(state.serverId)refreshPlayers()},30000);switchView(state.current);renderOnboarding()}
$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();$('#auth-error').textContent='';const body={username:$('#auth-user').value.trim(),password:$('#auth-pass').value};try{await api($('#auth-form').dataset.mode==='setup'?'/api/bootstrap':'/api/login',{method:'POST',body:JSON.stringify(body)});showApp()}catch(err){$('#auth-error').textContent=err.message}});$('#logout').addEventListener('click',async()=>{try{await api('/api/logout',{method:'POST'})}catch{}location.reload()});
$$('#nav button').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));$$('[data-view-tab]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.viewTab)));$$('[data-view-link]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.viewLink)));
function switchView(v){const dragon=selectedSummary()?.gameType==='runescape-dragonwilds';if(dragon&&['config','mods','backups'].includes(v))v='dashboard';state.current=v;$$('[data-view-tab="config"],[data-view-tab="mods"],[data-view-tab="backups"]').forEach(el=>el.classList.toggle('hidden',dragon));$('#console-form')?.classList.toggle('hidden',dragon);$('.players-panel')?.classList.toggle('hidden',dragon);$$('[data-action="auth"],[data-action="backup"]').forEach(el=>el.classList.toggle('hidden',dragon));$$('[data-update]').forEach(el=>el.closest('.panel')?.classList.toggle('hidden',dragon));$$('.view').forEach(x=>x.classList.remove('active'));const target=document.getElementById('view-'+v);if(target)target.classList.add('active');$('#nav button').forEach(x=>{const active=x.dataset.view===v;x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});$('[data-view-tab]').forEach(x=>{const active=x.dataset.viewTab===v;x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});const showTabs=!!state.serverId&&!['servers','app-settings'].includes(v);$('#server-tabs').classList.toggle('hidden',!showTabs);const titles={servers:'Servers',dashboard:'Overview',console:'Console',config:'Files',mods:'Mods',backups:'Backups',setup:'Install',settings:'Server settings','app-settings':'Application settings'};$('#view-title').textContent=titles[v]||'Servers';const global=v==='servers'||v==='app-settings';$('#top-status').classList.toggle('hidden',global||!state.serverId);$('#top-start').classList.toggle('hidden',global||!state.serverId);$('#top-context').textContent=global?'':(selectedSummary()?.serverName||'');loadCurrent()}

let managedPath='.', managedOpenPath='', managedDirty=false;
function filePathJoin(base,name){return base==='.'?name:base+'/'+name}
function fileSize(n){if(n<1024)return n+' B';if(n<1048576)return (n/1024).toFixed(1)+' KB';if(n<1073741824)return (n/1048576).toFixed(1)+' MB';return (n/1073741824).toFixed(2)+' GB'}
async function loadFiles(path=managedPath){managedPath=path||'.';const list=$('#managed-files');list.innerHTML='<div class="empty-state">Loading files…</div>';try{const d=await api('/api/files?path='+encodeURIComponent(managedPath));managedPath=d.path||'.';renderFileBreadcrumbs();if(!d.entries.length){list.innerHTML='<div class="empty-state">This folder is empty.</div>';return}list.innerHTML=d.entries.map(f=>'<div class="managed-file-row" data-path="'+esc(f.path)+'" data-directory="'+f.directory+'"><button class="managed-file-name" data-file-action="open" title="'+esc(f.name)+'"><span class="managed-file-icon '+(f.directory?'directory':'')+'">'+(f.directory?'▰':'▤')+'</span><span>'+esc(f.name)+'</span></button><span class="managed-file-size">'+(f.directory?'Folder':fileSize(f.size))+'</span><span class="managed-file-date">'+esc(fmtDate(f.modified))+'</span><span class="managed-file-actions"><button class="quiet-btn" data-file-action="download" title="Download" '+(f.directory?'disabled':'')+'>↓</button><button class="quiet-btn" data-file-action="rename">Rename</button><button class="quiet-btn danger-text" data-file-action="delete">Delete</button></span></div>').join('');$('#file-manager-note').textContent=d.entries.length+' item'+(d.entries.length===1?'':'s')+' · '+(managedPath==='.'?'/':managedPath)}catch(e){list.innerHTML='<div class="empty-state">'+esc(e.message)+'</div>'}}
function renderFileBreadcrumbs(){const el=$('#file-breadcrumbs');const parts=managedPath==='.'?[]:managedPath.split('/');let path='.';el.innerHTML='<button data-file-dir=".">Server files</button>'+parts.map(p=>{path=path==='.'?p:path+'/'+p;return '<span>›</span><button data-file-dir="'+esc(path)+'">'+esc(p)+'</button>'}).join('')}
function openManagedFolder(path){if(managedDirty&&!confirm('Discard unsaved file changes?'))return;managedDirty=false;$('#file-editor').classList.add('hidden');loadFiles(path)}
async function editManagedFile(path){if(managedDirty&&!confirm('Discard unsaved file changes?'))return;try{const d=await api('/api/files/content?path='+encodeURIComponent(path));managedOpenPath=d.path;managedDirty=false;$('#file-editor').classList.remove('hidden');$('#file-editor-name').textContent=d.name;$('#file-editor-meta').textContent=fileSize(d.size)+' · '+fmtDate(d.modified);$('#managed-file-content').value=d.content;$('#file-editor-status').textContent='Loaded';$('#file-editor-dirty').textContent='';$('#file-editor-warning').classList.add('hidden');$('#managed-file-content').oninput=()=>{managedDirty=true;$('#file-editor-dirty').textContent='Unsaved changes'};$('#file-editor').scrollIntoView({behavior:'smooth',block:'nearest'})}catch(e){toast(e.message,true)}}
async function saveManagedFile(){if(!managedOpenPath)return;const btn=$('#file-editor-save');btn.disabled=true;try{await api('/api/files/content',{method:'PUT',body:JSON.stringify({path:managedOpenPath,content:$('#managed-file-content').value})});managedDirty=false;$('#file-editor-status').textContent='Saved '+new Date().toLocaleTimeString();$('#file-editor-dirty').textContent='';toast('File saved');await loadFiles(managedPath)}catch(e){toast(e.message,true);$('#file-editor-status').textContent=e.message}finally{btn.disabled=false}}
async function downloadManagedFile(path){try{const res=await fetch('/api/files/download?path='+encodeURIComponent(path),{headers:{'X-HSM-Server':state.serverId}});if(!res.ok){let b={};try{b=await res.json()}catch{}throw new Error(b.error||'Download failed')}const blob=await res.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=path.split('/').pop();document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}catch(e){toast(e.message,true)}}
async function deleteManagedFile(path){if(!confirm('Permanently delete "'+path.split('/').pop()+'" and its contents if it is a folder? This cannot be undone.'))return;try{await api('/api/files?path='+encodeURIComponent(path),{method:'DELETE'});if(managedOpenPath===path){managedOpenPath='';managedDirty=false;$('#file-editor').classList.add('hidden')}await loadFiles(managedPath);toast('Deleted')}catch(e){toast(e.message,true)}}
async function renameManagedFile(path){const old=path.split('/').pop(),name=prompt('New name',old);if(name===null||!name.trim()||name===old)return;try{const d=await api('/api/files/rename',{method:'POST',body:JSON.stringify({path,name:name.trim()})});if(managedOpenPath===path){managedOpenPath=d.path;$('#file-editor-name').textContent=name.trim()}await loadFiles(managedPath);toast('Renamed')}catch(e){toast(e.message,true)}}
async function createManagedFolder(){const name=prompt('Folder name');if(name===null||!name.trim())return;try{await api('/api/files/mkdir',{method:'POST',body:JSON.stringify({path:filePathJoin(managedPath,name.trim())})});await loadFiles(managedPath);toast('Folder created')}catch(e){toast(e.message,true)}}
async function createManagedFile(){const name=prompt('New file name');if(name===null||!name.trim())return;const path=filePathJoin(managedPath,name.trim());try{await api('/api/files/content',{method:'PUT',body:JSON.stringify({path,content:''})});await loadFiles(managedPath);await editManagedFile(path);toast('File created')}catch(e){toast(e.message,true)}}
async function uploadManagedFiles(files){for(const file of files){const form=new FormData();form.append('file',file);form.append('path',managedPath);try{await api('/api/files/upload',{method:'POST',body:form});toast('Uploaded '+file.name)}catch(e){toast(file.name+': '+e.message,true)}}$('#file-upload').value='';await loadFiles(managedPath)}
$('#managed-files').addEventListener('click',e=>{const action=e.target.closest('[data-file-action]');const row=e.target.closest('.managed-file-row');if(!row)return;const path=row.dataset.path;switch(action?.dataset.fileAction){case'open':row.dataset.directory==='true'?openManagedFolder(path):editManagedFile(path);break;case'download':downloadManagedFile(path);break;case'rename':renameManagedFile(path);break;case'delete':deleteManagedFile(path);break;}});
$('#file-breadcrumbs').addEventListener('click',e=>{const b=e.target.closest('[data-file-dir]');if(b)openManagedFolder(b.dataset.fileDir)});
$('#file-refresh').addEventListener('click',()=>loadFiles(managedPath));
$('#file-new-folder').addEventListener('click',createManagedFolder);
$('#file-new-file').addEventListener('click',createManagedFile);
$('#file-upload').addEventListener('change',e=>{if(e.target.files&&e.target.files.length)uploadManagedFiles([...e.target.files])});
$('#file-editor-save').addEventListener('click',saveManagedFile);
$('#file-editor-close').addEventListener('click',()=>{if(managedDirty&&!confirm('Discard unsaved file changes?'))return;managedDirty=false;managedOpenPath='';$('#file-editor').classList.add('hidden')});

function loadCurrent(){if(state.current==='servers')renderFleet();if(state.current==='app-settings')loadAppUpdate();if(!state.serverId)return;if(state.current==='mods')loadMods();if(state.current==='backups')loadBackups();if(state.current==='config')loadFiles();if(state.current==='setup')loadInstallStatus()}
async function loadServers(initial=false){try{state.servers=await api('/api/servers');const saved=localStorage.getItem('hsm-server');if(!state.servers.length){state.serverId=null;state.settings=null;state.status=null;state.logs=[];state.events?.close();state.events=null;renderServerList();renderFleet();renderFleetStats();populateCloneSources();renderOnboarding();if(initial)switchView('servers');return}if(!state.serverId||!state.servers.some(s=>s.id===state.serverId)){state.serverId=(saved&&state.servers.some(s=>s.id===saved))?saved:state.servers[0].id}renderServerList();renderFleet();renderFleetStats();populateCloneSources();renderOnboarding();if(initial)$('#top-context').textContent=selectedSummary()?.serverName||''}catch(e){if(initial)toast(e.message,true)}}
function renderFleetStats(){const online=state.servers.filter(s=>s.running).length;$('#fleet-online').textContent=online;$('#fleet-total').textContent=state.servers.length;const installed=state.servers.filter(s=>s.installed).length;$('#fleet-summary').innerHTML=`<div><strong>${state.servers.length}</strong><span>Instances</span></div><div><strong>${online}</strong><span>Online</span></div><div><strong>${installed}</strong><span>Installed</span></div><div><strong>${state.servers.length-online}</strong><span>Stopped</span></div>`}
function renderServerList(){const el=$('#server-list');el.innerHTML=state.servers.map(s=>`<button class="server-list-item ${s.id===state.serverId?'active':''}" data-select-server="${esc(s.id)}" aria-pressed="${s.id===state.serverId?'true':'false'}"><span class="game-icon game-icon-${esc(s.gameType)}" aria-hidden="true">${gameLogo(s.gameType)}</span><span class="server-list-copy"><b>${esc(s.serverName)}</b><small>${esc(gameLabel(s.gameType))} · ${statusLabel(s)} · UDP ${s.port}</small></span></button>`).join('');$$('[data-select-server]').forEach(b=>b.addEventListener('click',()=>selectServer(b.dataset.selectServer)))}

async function loadAppUpdate(){const check=$('#app-update-check');if(check)check.disabled=true;$('#app-update-message').textContent='Checking GitHub for the latest stable release…';try{const info=await api('/api/app-update');state.appUpdate=info;renderAppUpdate(info)}catch(e){$('#app-update-badge').textContent='Check failed';$('#app-update-message').textContent=e.message;$('#app-update-apply').disabled=true}finally{if(check)check.disabled=false}}
function renderAppUpdate(info){$('#app-update-current').textContent='v'+(info.currentVersion||'unknown');$('#app-update-latest').textContent='v'+(info.latestVersion||info.currentVersion||'unknown');$('#app-update-date').textContent=info.publishedAt?fmtDate(info.publishedAt):'—';const badge=$('#app-update-badge');badge.textContent=info.updateAvailable?'Update available':(info.status==='updating'?'Updating…':(info.message?.includes('No stable release')?'No release yet':'Up to date'));badge.className='update-badge'+(info.updateAvailable?' available':'');$('#app-update-message').textContent=info.message||(info.updateAvailable?'A newer stable version is ready to install.':'You are running the latest release.');$('#app-update-apply').disabled=!info.updateAvailable||!info.updaterReady||info.status==='updating'||info.status==='starting';$('#app-update-apply').textContent=info.status==='updating'?'Updating…':'Update and restart';const link=$('#app-update-release-link');if(info.releaseUrl&&info.releaseUrl.startsWith('https://github.com/SrFarsquatch/Hytale-Server-Manager/releases/')){link.href=info.releaseUrl;link.classList.remove('hidden')}else link.classList.add('hidden');const notes=$('#app-update-notes');if(info.releaseNotes?.trim()){notes.textContent=info.releaseNotes;notes.classList.remove('hidden')}else{notes.textContent='';notes.classList.add('hidden')}}
$('#app-update-check').addEventListener('click',loadAppUpdate);
$('#app-update-apply').addEventListener('click',async()=>{const info=state.appUpdate;if(!info?.updateAvailable||!info.updaterReady)return;if(!confirm('Update Hytale Server Manager to v'+info.latestVersion+'? The dashboard will briefly go offline while the container restarts. Your server data volume and game worlds will be preserved.'))return;const btn=$('#app-update-apply');btn.disabled=true;btn.textContent='Starting update…';$('#app-update-badge').textContent='Updating…';$('#app-update-message').textContent='Preparing the update. Keep this page open while the manager restarts.';try{const result=await api('/api/app-update',{method:'POST',body:'{}'});$('#app-update-message').textContent=result.message||'Update started. Waiting for the new version…';waitForAppVersion(info.latestVersion)}catch(e){toast(e.message,true);$('#app-update-message').textContent=e.message;await loadAppUpdate()}});
async function waitForAppVersion(target){for(let i=0;i<100;i++){await new Promise(resolve=>setTimeout(resolve,3000));try{const health=await fetch('/api/health',{cache:'no-store'});if(health.ok){const body=await health.json();if(String(body.version||'').replace(/^v/,'')===String(target).replace(/^v/,'')){toast('Updated successfully to v'+target);setTimeout(()=>location.reload(),900);return}}}catch{}}$('#app-update-message').textContent='The update is taking longer than expected. Refresh this page in a moment to check the manager status.';$('#app-update-apply').disabled=false}

function renderOnboarding(){const empty=state.servers.length===0;$('#app').classList.toggle('onboarding',empty);$('#first-run')?.classList.toggle('hidden',!empty);$('#fleet-content')?.classList.toggle('hidden',empty);$('#server-list')?.classList.toggle('hidden',empty);$('#add-server-side')?.classList.toggle('hidden',empty);if(empty){$('#view-title').textContent='Welcome';$('#top-context').textContent='';$('#top-status').classList.add('hidden');$('#top-start').classList.add('hidden')}else if(state.current==='servers')$('#view-title').textContent='Servers'}
function renderFleet(){if(!$('#fleet-grid'))return;const grid=$('#fleet-grid');if(!state.servers.length){grid.innerHTML='<div class="empty-state" style="padding:16px">No servers configured.</div>';return}grid.innerHTML=state.servers.map(s=>{const transitioning=s.state==='starting'||s.state==='stopping';const action=s.running?'stop':s.installed?'start':'install';const actionLabel=s.state==='starting'?'Starting…':s.state==='stopping'?'Stopping…':s.installBusy?'Installing…':s.running?'Stop':s.installed?'Start':'Install';return `<article class="fleet-card ${s.id===state.serverId?'selected':''}"><button class="fleet-open" data-fleet-open="${esc(s.id)}"><div class="fleet-name"><span class="game-icon game-icon-${esc(s.gameType)}" aria-hidden="true">${gameIcon(s.gameType)}</span><strong>${esc(s.serverName)}${s.primary?'<span class="primary-tag">primary</span>':''}</strong><small>${esc(gameLabel(s.gameType))} · UDP ${s.port}</small></div><div class="fleet-cell fleet-status"><span class="dot ${statusDotClass(s)}"></span>${esc(statusLabel(s))}</div><div class="fleet-cell fleet-address">${esc(s.publicHost||location.hostname)}:${s.port}</div><div class="fleet-cell fleet-uptime">${s.running?fmtUptime(s.uptimeSeconds):'—'}</div><div class="fleet-cell fleet-files">${s.installed?'Ready':'Missing'}</div></button><div class="fleet-actions"><button class="btn small ${s.running?'':'success'}" data-fleet-action="${action}" data-id="${esc(s.id)}" ${transitioning||s.installBusy?'disabled':''}>${actionLabel}</button><button class="btn small" data-fleet-open="${esc(s.id)}">Open</button></div></article>`}).join('');$$('[data-fleet-open]').forEach(b=>b.addEventListener('click',()=>selectServer(b.dataset.fleetOpen)));$$('[data-fleet-action]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();fleetAction(b.dataset.id,b.dataset.fleetAction)}))}
async function selectServer(id){if(!id||!state.servers.some(s=>s.id===id))return;if(id===state.serverId){switchView('dashboard');return}state.events?.close();state.events=null;state.serverId=id;localStorage.setItem('hsm-server',id);state.logs=[];state.settings=null;state.status=null;state.resources=null;state.players=null;managedPath='.';managedOpenPath='';managedDirty=false;renderServerList();renderFleet();switchView('dashboard');await loadSelected()}
async function loadSelected(){if(!state.serverId)return;await Promise.all([loadSettings(),refreshStatus(),refreshResources(),loadLogs(),refreshPlayers()]);connectEvents();loadCurrent()}
async function fleetAction(id,action){if(action==='install'){await selectServer(id);switchView('setup');return}const server=state.servers.find(s=>s.id===id);if(action==='stop'&&!confirm(`Stop ${server?.serverName||'this server'}? Players may be disconnected.`))return;try{await api(`/api/servers/${encodeURIComponent(id)}/${action}`,{method:'POST'});toast(`${action==='start'?'Start':'Stop'} requested`);setTimeout(async()=>{await loadServers(false);if(id===state.serverId)await refreshStatus()},450)}catch(e){toast(e.message,true)}}
async function refreshPlayers(){if(!state.serverId)return;const id=state.serverId;const button=$('#players-refresh');if(button)button.disabled=true;try{const players=await api('/api/players');if(id!==state.serverId)return;state.players=players;renderPlayers()}catch(e){if(id!==state.serverId)return;state.players={known:false,players:[],message:e.message};renderPlayers()}finally{if(button&&id===state.serverId)button.disabled=false}}
function renderPlayers(){const p=state.players;if(!p)return;$('#metric-players').textContent=p.known?(p.count+' / '+p.maxPlayers):'Unknown';$('#players-message').textContent=p.message||(p.known?'Live player list':'Player count could not be verified');$('#players-list').innerHTML=p.known?(p.players&&p.players.length?p.players.map(name=>'<span class="player-chip">'+esc(name)+'</span>').join(''):'<span class="muted">No players online.</span>'):'<span class="muted">The server response was not recognized. Check Console for the /who output.</span>'}
$('#players-refresh').addEventListener('click',refreshPlayers);
async function refreshStatus(){if(!state.serverId)return;const id=state.serverId;try{const status=await api('/api/status');if(id!==state.serverId)return;state.status=status;renderStatus()}catch{}}
async function refreshResources(){if(!state.serverId)return;const id=state.serverId;try{const resources=await api('/api/resources');if(id!==state.serverId)return;state.resources=resources;renderResources()}catch{}}
function renderResources(){const r=state.resources;if(!r)return;const cpu=$('#resource-cpu-value'),cpuBar=$('#resource-cpu-bar'),mem=$('#resource-memory-value'),memBar=$('#resource-memory-bar'),disk=$('#resource-disk-value'),diskBar=$('#resource-disk-bar');cpu.textContent=r.cpuAvailable?r.cpuPercent.toFixed(1)+'%':'Unavailable';cpuBar.style.width=r.cpuAvailable?Math.min(100,Math.max(0,r.cpuPercent))+'%':'0%';cpuBar.classList.toggle('warning',r.cpuAvailable&&r.cpuPercent>=80);cpuBar.classList.toggle('critical',r.cpuAvailable&&r.cpuPercent>=95);mem.textContent=r.memoryAvailable?fmtBytes(r.containerMemoryBytes)+(r.containerMemoryLimitBytes>0?' / '+fmtBytes(r.containerMemoryLimitBytes):' used'):'Unavailable';const mp=r.memoryAvailable&&r.containerMemoryLimitBytes>0?Math.min(100,r.containerMemoryBytes/r.containerMemoryLimitBytes*100):0;memBar.style.width=mp+'%';memBar.classList.toggle('warning',mp>=80);memBar.classList.toggle('critical',mp>=95);disk.textContent=r.diskAvailable?fmtBytes(r.diskUsedBytes)+' / '+fmtBytes(r.diskTotalBytes)+' · '+fmtBytes(r.diskFreeBytes)+' free':'Unavailable';const dp=r.diskAvailable&&r.diskTotalBytes>0?Math.min(100,r.diskUsedBytes/r.diskTotalBytes*100):0;diskBar.style.width=dp+'%';diskBar.classList.toggle('warning',dp>=80);diskBar.classList.toggle('critical',dp>=95);$('#resource-sampled').textContent=r.sampledAt?'Updated '+fmtTime(r.sampledAt):'Waiting for metrics';}
function renderStatus(){const s=state.status,on=s?.running,busy=s?.installBusy,transitioning=s?.state==='starting'||s?.state==='stopping',label=statusLabel(s);$('#top-status').innerHTML=`<span class="dot ${statusDotClass(s)}"></span><span>${esc(label)}</span>`;$('#hero-dot').className='dot large '+statusDotClass(s);$('#hero-state').textContent=label.toUpperCase();const detail=s?.state==='crashed'?`Process exited with code ${s.exitCode}${s.lastExitAt?' at '+fmtDate(s.lastExitAt):''}. Check Recent output for the error.`:s?.state==='starting'?'The server process has launched; waiting for it to finish initializing.':s?.state==='stopping'?'A graceful shutdown was requested. Waiting for the process to exit.':s?.state==='not-installed'?'Install server files to start this instance.':s?.lastExitAt?`Last exit: ${fmtDate(s.lastExitAt)}.`:'';$('#hero-detail').textContent=detail;$('#hero-detail').classList.toggle('hidden',!detail);$('#metric-uptime').textContent=fmtUptime(s?.uptimeSeconds);$('#metric-memory').textContent=fmtBytes(s?.memoryBytes);$('#metric-memory-limit').textContent=fmtBytes(s?.memoryLimitBytes);$('#metric-installed').textContent=s?.installed?'Ready':'Missing';$('#memory-warning').classList.toggle('hidden',s?.meetsMinimumMemory!==false);$('#start-btn').disabled=on||busy||!s?.installed;$('#top-start').disabled=on||busy||!s?.installed;$('#stop-btn').disabled=!on||s?.state==='stopping';$('#restart-btn').disabled=!on||transitioning||busy;$('#top-start').textContent=s?.state==='starting'?'Starting…':s?.state==='stopping'?'Stopping…':on?'Running':s?.installed?'Start':'Install';if(state.settings){$('#metric-port').textContent=state.settings.port;updateAddress()}if(state.current==='config')setConfigEditState(!on)}
