const dialog=$('#server-dialog');let wizardStep=0;const wizardTitles=['Choose your game','The basics','Game settings','Resources & review'];function setWizardStep(step){wizardStep=Math.max(0,Math.min(3,step));$$('[data-wizard-step]').forEach(el=>el.classList.toggle('hidden',Number(el.dataset.wizardStep)!==wizardStep));$('#wizard-step-label').textContent='STEP '+(wizardStep+1)+' OF 4';$('#wizard-step-title').textContent=wizardTitles[wizardStep];$('#wizard-progress-fill').style.width=((wizardStep+1)*25)+'%';$('#wizard-back').classList.toggle('hidden',wizardStep===0);$('#wizard-next').classList.toggle('hidden',wizardStep===3);$('#wizard-create').classList.toggle('hidden',wizardStep!==3);if(wizardStep===3)renderWizardReview()}
function syncGameSpecificFields(){
 const dragon=state.selectedGame==='runescape-dragonwilds';
 $('#dragonwilds-fields')?.classList.toggle('hidden',!dragon);
 $$('.hytale-only').forEach(el=>el.classList.toggle('hidden',dragon));
 ['new-server-xms','new-server-xmx','new-server-backup'].forEach(id=>{const input=$('#'+id);if(input){input.disabled=dragon;input.required=!dragon}});['new-dragonwilds-owner','new-dragonwilds-world','new-dragonwilds-admin','new-dragonwilds-password'].forEach(id=>{const input=$('#'+id);if(input){input.disabled=!dragon;input.required=dragon&&id!=='new-dragonwilds-password'}});
 const note=$('#wizard-config-note');
 if(note)note.textContent=dragon?'Dragonwilds requires an Owner ID, server name, default world name and admin password. World password is optional. HSM writes the INI values before launch.':'When enabled, Hytale requires join permission for players. You can manage player permissions from the server console.';
 if(dragon){
  if($('#new-server-name').value==='My Hytale Server'||$('#new-server-name').value==='New Hytale Server')$('#new-server-name').value='My Dragonwilds Server';
  $('#new-server-players').value=6;
  $('#new-server-motd').value='';
  $('#new-port-help').textContent='Dragonwilds uses UDP 7777–7782. Leave blank to use the first available Dragonwilds port.';
 }else{
  if($('#new-server-name').value==='My Dragonwilds Server')$('#new-server-name').value=state.servers.length?'New Hytale Server':'My Hytale Server';
  $('#new-server-players').value=20;
  $('#new-server-motd').value='Welcome to your Hytale server!';
  $('#new-port-help').textContent='Leave blank to assign the next available port in the published range.';
 }
}
function renderGameChoices(){const el=$('#game-choice-list');if(!el||!state.games.length)return;el.innerHTML=state.games.map(g=>{const ready=!!g.available;const selected=state.selectedGame===g.id&&ready;const detail=ready?'Dedicated server · Ready to configure':'Planned · Not available yet';return '<button type="button" class="game-choice'+(selected?' selected':'')+'" data-game-choice="'+esc(g.id)+'" '+(ready?'':'disabled')+'><span class="game-icon">'+esc(g.name.slice(0,1))+'</span><span><strong>'+esc(g.name)+'</strong><small>'+esc(detail)+'</small></span><span class="choice-check">'+(selected?'✓':'')+'</span></button>'}).join('');$$('[data-game-choice]:not(:disabled)').forEach(b=>b.addEventListener('click',()=>{state.selectedGame=b.dataset.gameChoice;syncGameSpecificFields();populateCloneSources();renderGameChoices()}))}
async function loadGameChoices(){try{const data=await api('/api/games');state.games=data.games||[];if(!state.games.some(g=>g.id===state.selectedGame&&g.available))state.selectedGame=state.games.find(g=>g.available)?.id||'hytale';renderGameChoices()}catch(e){toast('Could not load game catalog: '+e.message,true)}}
function openServerDialog(){wizardStep=0;state.selectedGame='hytale';setWizardStep(0);loadGameChoices();$('#new-server-name').value=state.servers.length?'New Hytale Server':'My Hytale Server';$('#new-server-port').value='';$('#new-server-host').value='';$('#new-server-mode').value='Adventure';$('#new-server-players').value=20;$('#new-server-motd').value='Welcome to your Hytale server!';$('#new-server-password').value='';$('#new-server-whitelist').checked=false;$('#new-server-xms').value='2G';$('#new-server-xmx').value='4G';$('#new-server-backup').value=30;$('#new-server-autostart').checked=false;$('#new-dragonwilds-owner').value='';$('#new-dragonwilds-world').value='Dragonwilds World';$('#new-dragonwilds-admin').value='';$('#new-dragonwilds-password').value='';syncGameSpecificFields();const ports=state.settings||{};$('#new-port-help').textContent=ports.portMin?'Leave blank for the next available port in '+ports.portMin+'–'+ports.portMax+'.':'Leave blank for the next available published port.';populateCloneSources();dialog.showModal()}
function closeServerDialog(){dialog.close()}$('#add-server-side').addEventListener('click',openServerDialog);$('#add-server-main').addEventListener('click',openServerDialog);$('#first-create').addEventListener('click',openServerDialog);$('#cancel-server-dialog').addEventListener('click',closeServerDialog);$('#wizard-back').addEventListener('click',()=>setWizardStep(wizardStep-1));$('#wizard-next').addEventListener('click',()=>{if(wizardStep===1){const name=$('#new-server-name').value.trim();if(name.length<2||name.length>64){toast('Server name must be between 2 and 64 characters',true);return}const p=$('#new-server-port').value;if(p&&(+p<1||+p>65535)){toast('Enter a valid UDP port',true);return}}if(wizardStep===2){const players=+$('#new-server-players').value;if(players<1||players>(state.selectedGame==='runescape-dragonwilds'?6:1000)){toast(state.selectedGame==='runescape-dragonwilds'?'Dragonwilds supports up to 6 players':'Maximum players must be between 1 and 1000',true);return}if(state.selectedGame==='runescape-dragonwilds'){if(!$('#new-dragonwilds-owner').value.trim()){toast('Enter your Dragonwilds Owner ID',true);return}if(!$('#new-dragonwilds-admin').value){toast('Set a Dragonwilds admin password',true);return}}}setWizardStep(wizardStep+1)});
function renderWizardReview(){const chosen=state.games.find(g=>g.id===state.selectedGame);const dragon=state.selectedGame==='runescape-dragonwilds';const items=[['Game',chosen?.name||'Hytale'],['Server name',$('#new-server-name').value.trim()],['Game port',$('#new-server-port').value||'Automatic']];if(dragon){items.push(['Owner ID',$('#new-dragonwilds-owner').value.trim()],['Default world',$('#new-dragonwilds-world').value.trim()],['Admin password',$('#new-dragonwilds-admin').value?'Configured':'Missing'],['World password',$('#new-dragonwilds-password').value?'Set':'Not set'],['Capacity','Up to 6 players (game limit)'])}else{items.push(['Players',$('#new-server-players').value],['Backups','Every '+$('#new-server-backup').value+' minutes'],['Game mode',$('#new-server-mode').value],['Whitelist',$('#new-server-whitelist').checked?'Enabled':'Disabled'],['Memory',$('#new-server-xms').value+' – '+$('#new-server-xmx').value],['Access',$('#new-server-password').value?'Password protected':'No password'])}$('#wizard-review').innerHTML=items.map(([label,value])=>'<div class="review-item"><small>'+esc(label)+'</small><strong>'+esc(value)+'</strong></div>').join('')}
function populateCloneSources(){const sel=$('#new-server-source'),current=sel.value;sel.innerHTML='<option value="">Fresh install — set up game files next</option>'+state.servers.filter(s=>s.installed&&s.gameType===state.selectedGame).map(s=>'<option value="'+esc(s.id)+'">Clone '+esc(s.serverName)+' (new world)</option>').join('');if([...sel.options].some(o=>o.value===current))sel.value=current}
function validMemoryInput(v){return /^\d+(?:K|M|G)$/i.test(v.trim())&&Number(v.trim().slice(0,-1))>0}
$('#server-create-form').addEventListener('submit',async e=>{e.preventDefault();const body={game:state.selectedGame||'hytale',name:$('#new-server-name').value.trim(),port:+$('#new-server-port').value||0,publicHost:$('#new-server-host').value.trim(),gameMode:$('#new-server-mode').value,maxPlayers:+$('#new-server-players').value,motd:$('#new-server-motd').value.trim(),password:$('#new-server-password').value,whitelistEnabled:$('#new-server-whitelist').checked,memoryMin:$('#new-server-xms').value.trim(),memoryMax:$('#new-server-xmx').value.trim(),backupFrequency:+$('#new-server-backup').value,autoStart:$('#new-server-autostart').checked,sourceServerId:$('#new-server-source').value,dragonwildsOwnerId:$('#new-dragonwilds-owner').value.trim(),dragonwildsWorldName:$('#new-dragonwilds-world').value.trim(),dragonwildsAdminPassword:$('#new-dragonwilds-admin').value,dragonwildsWorldPassword:$('#new-dragonwilds-password').value};if(state.selectedGame==='hytale'&&(!validMemoryInput(body.memoryMin)||!validMemoryInput(body.memoryMax))){toast('Memory values must look like 2G, 4096M or 1024K',true);setWizardStep(3);return}try{const s=await api('/api/servers',{method:'POST',body:JSON.stringify(body)});closeServerDialog();toast('Server created');state.serverId=s.id;localStorage.setItem('hsm-server',s.id);await loadServers(false);await loadSelected();if(!body.sourceServerId)switchView('setup');else switchView('dashboard')}catch(err){toast(err.message,true)}});
boot().catch(e=>{document.body.innerHTML=`<pre style="padding:30px;color:#e29a96">${esc(e.stack||e.message)}</pre>`});
